(function(){
'use strict';
if(typeof ToPRGAdv==='undefined'){console.error('[RICO TEST50] ToPRGAdv missing');return;}
var TEMPLATES={up:'',down:'',left:'',right:''};
var LOAD=0x0801, SCREEN=0x4000, CHARSET=0x3000, CFG=0x2fe0;
function decode(s){var r=atob(s),u=new Uint8Array(r.length);for(var i=0;i<r.length;i++)u[i]=r.charCodeAt(i)&255;return u;}
function idx(addr){return 2+(addr-LOAD);}
function put(bytes,addr,v){var i=idx(addr);if(i>=0&&i<bytes.length)bytes[i]=v&255;}
function getTileSet(editor){try{var l=editor.layers.getSelectedLayerObject();if(l&&l.getType&&l.getType()==='grid'&&l.getTileSet)return l.getTileSet();return editor.tileSetManager.getCurrentTileSet();}catch(e){return null;}}
function getBank2(ts){try{var r=ts.getDocRecord&&ts.getDocRecord(),d=r&&r.data&&r.data.ricoCharsetBank2;if(d&&d.tileData&&d.tileData.length>=256)return d.tileData;}catch(e){}return null;}
function pixels(tile){return tile&&tile.data&&tile.data.length?tile.data[0]:null;}
function charsetBytes(data,fallback){var o=new Uint8Array(2048);for(var c=0;c<256;c++){var p=pixels(data&&data[c])||pixels(fallback&&fallback[c]);if(!p)continue;for(var y=0;y<8;y++){var b=0;for(var x=0;x<8;x++)if(p[y*8+x])b|=1<<(7-x);o[c*8+y]=b;}}return o;}
function cfg(editor){try{if(window.RICO_TEST37_MAP_SCROLL&&window.RICO_TEST37_MAP_SCROLL.getConfig)return window.RICO_TEST37_MAP_SCROLL.getConfig(editor.graphic,0);var f=editor.graphic.frames&&editor.graphic.frames[0],c=f&&f.ricoMapScrollV1;return c||{type:'',ticksPerStep:6,pixelsPerStep:1};}catch(e){return {type:'',ticksPerStep:6,pixelsPerStep:1};}}
function frameCount(editor){try{return editor.graphic.getFrameCount();}catch(e){return editor.graphic.frames?editor.graphic.frames.length:0;}}
function clamp(v,a,b,d){v=parseInt(v,10);return isNaN(v)?d:Math.max(a,Math.min(b,v));}
function colorIndex(v,d){v=parseInt(v,10);return isNaN(v)||v<0?d:(v&15);}
function dominantColor(layer){var h=new Array(16).fill(0);for(var y=0;y<25;y++)for(var x=0;x<40;x++){try{var c=layer.getCell({x:x,y:y,frame:0}),fc=colorIndex(c&&c.fc,14);h[fc]++;}catch(e){}}var best=14,n=-1;for(var i=0;i<16;i++)if(h[i]>n){n=h[i];best=i;}return best;}
function supports(self,args){var ed=self.editor;if(!ed||frameCount(ed)!==1)return false;var c=cfg(ed);if(!TEMPLATES[c.type])return false;var l=ed.layers&&ed.layers.getSelectedLayerObject?ed.layers.getSelectedLayerObject():null;if(!l||!l.getType||l.getType()!=='grid')return false;var ts=getTileSet(ed);if(!ts||ts.getTileWidth()!=8||ts.getTileHeight()!=8)return false;var w=args&&args.gridWidth?parseInt(args.gridWidth,10):40,h=args&&args.gridHeight?parseInt(args.gridHeight,10):25;return w===40&&h===25;}
function fillProject(bytes,self,c){var ed=self.editor,l=ed.layers.getSelectedLayerObject(),ts=getTileSet(ed);var frame=ed.graphic.frames&&ed.graphic.frames[0]||{};var data=ts.tileData;if(parseInt(frame.charsetBank,10)===2){var b2=getBank2(ts);if(b2)data=b2;}bytes.set(charsetBytes(data,ts.tileData),idx(CHARSET));var si=idx(SCREEN);for(var y=0;y<25;y++)for(var x=0;x<40;x++){var t=0;try{var cell=l.getCell({x:x,y:y,frame:0});t=parseInt(cell&&cell.t,10);if(isNaN(t)||t<0||t>255)t=0;}catch(e){t=0;}bytes[si+y*40+x]=t&255;}var bg=0,br=0;try{bg=colorIndex(l.getBackgroundColor(0),0);}catch(e){}try{br=colorIndex(l.getBorderColor(0),bg);}catch(e){br=bg;}var fg=dominantColor(l);var ticks=clamp(c.ticksPerStep,1,255,4),px=clamp(c.pixelsPerStep,1,8,1);return {bg:bg,br:br,fg:fg,ticks:ticks,px:px};}
function buildUp(self,c){var bytes=decode(TEMPLATES.up),v=fillProject(bytes,self,c);put(bytes,0x201f,v.bg);put(bytes,0x2024,v.br);put(bytes,0x206d,v.fg);put(bytes,0x209b,v.ticks);put(bytes,0x209f,v.ticks);put(bytes,0x20dd,0x20);put(bytes,0x20de,0xc3);put(bytes,0x20df,0x21);var r=[0xa2,v.px,0x20,0xe6,0x20,0xca,0xd0,0xfa,0x60];for(var q=0;q<r.length;q++)put(bytes,0x21c3+q,r[q]);/* C64 vertical smooth-scroll mask: 24-row mode (RSEL=0), hides the top/bottom transition seam */put(bytes,0x20c0,0x17);put(bytes,0x20ef,0x10);put(bytes,0x2100,0x10);return {bytes:bytes,v:v};}
function buildNew(self,c){var bytes=decode(TEMPLATES[c.type]),v=fillProject(bytes,self,c);put(bytes,CFG,v.bg);put(bytes,CFG+1,v.br);put(bytes,CFG+2,v.fg);put(bytes,CFG+3,v.ticks);put(bytes,CFG+4,v.px);if(c.type==='down'){/* 24-row mode for clean vertical borders */put(bytes,0x20c2,0x10);put(bytes,0x20ff,0x10);put(bytes,0x2110,0x10);}return {bytes:bytes,v:v};}
var prev=ToPRGAdv.prototype.createPRG;
ToPRGAdv.prototype.createPRG=function(args){args=args||{};if(!supports(this,args))return prev.apply(this,arguments);var c=cfg(this.editor),r=c.type==='up'?buildUp(this,c):buildNew(this,c),bytes=r.bytes,v=r.v;this.prg=bytes;var fn=args.filename||('rico-map-scroll-'+c.type+'.prg');if(!/\.prg$/i.test(fn))fn+='.prg';console.log('[RICO TEST50] Standalone MAP SCROLL '+c.type+' runtime. ticks='+v.ticks+', px='+v.px+', bg='+v.bg+', fg='+v.fg+'.');if(args.download===false)return bytes;if(typeof window.download==='function'){window.download(bytes,fn,'application/prg');return bytes;}console.error('[RICO TEST50] download() missing');return bytes;};
window.RICO_TEST50_PRG_MAP_SCROLL=true;
console.log('[RICO TEST50] PRG MAP SCROLL wrap directions installed: Up (proven TEST48), Down, Left, Right.');
})();
